#!/usr/bin/env python3
from pathlib import Path
import json,base64,html
R=Path(__file__).resolve().parent.parent
M=json.loads((R/'source/master.json').read_text())
def art(name,cls='',height=None):
 folder='comparison' if name.startswith('comparison') else 'svg'
 raw=(R/folder/(name+'.svg')).read_text()
 # SVG data URI inherits no page styles; theme switches through two exact color exports.
 raw2=(R/folder/(name+'-reverse.svg')).read_text()
 d=M['layouts'][name];hh=height*(d['height']+2*d['padding'])/d['height'] if height else None
 st=f'height:{hh:g}px;width:auto;max-width:none' if hh else ''
 return '<span class="art '+cls+'" style="'+st+'">'+''.join(f'<img class="{mode}" src="data:image/svg+xml;base64,{base64.b64encode(data.encode()).decode()}" alt="{html.escape(name)}" style="{st}"/>' for mode,data in [('positive',raw),('negative',raw2)])+'</span>'
def icon(name,size):
 out=''
 for mode,suf in [('positive',''),('negative','-reverse')]:
  raw=(R/'svg'/(name+suf+'-square.svg')).read_bytes()
  out+=f'<img class="{mode}" width="{size}" height="{size}" src="data:image/svg+xml;base64,{base64.b64encode(raw).decode()}" alt="{name} at {size}px"/>'
 return '<span class="icon">'+out+'</span>'
original=base64.b64encode((R/'reference/loamcommons-logo.png').read_bytes()).decode()
L=M['paths']['L'];C=M['paths']['C']
construction=f'''<svg viewBox="-260 -260 1540 1540" role="img" aria-label="L and C construction with height, stem and clear-space guides"><title>One shared L, one companion C</title><g fill="currentColor"><path id="construction-l" d="{L}"><title>L: four cubic segments</title></path><path id="construction-c" d="{C}"><title>C: seven cubic segments</title></path></g><g fill="none" stroke="var(--muted)" stroke-width="3" stroke-dasharray="9 9"><rect x="-200" y="-200" width="1330" height="1400"/><path d="M-90 0H1000 M-90 1000H1000 M0 530H231 M231 620V1100 M284 400V1100 M0 779H1060"/></g><g font-family="Arial,sans-serif" font-size="44" fill="currentColor"><text x="975" y="35">0</text><text x="975" y="1015">1000</text><text x="25" y="505">231</text><text x="430" y="1160">48 min channel</text></g></svg>'''
# All info design uses the existing identity's monochrome palette, no new brand direction.
head='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Loam — Identity master</title><style>
:root{--bg:#fff;--ink:#151515;--muted:#707070;--line:#d9d9d9;--panel:#f6f6f4;color-scheme:light}*{box-sizing:border-box;min-width:0}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,"Helvetica Neue",sans-serif}body.dark{--bg:#151515;--ink:#fff;--muted:#aaa;--line:#454545;--panel:#202020;color-scheme:dark}main{max-width:1200px;margin:auto;padding:32px 36px 80px}nav{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap;border-bottom:1px solid var(--line);padding-bottom:18px}nav div{display:flex;gap:8px;flex-wrap:wrap}button,a.button{font:inherit;border:1px solid var(--line);border-radius:30px;background:var(--bg);color:var(--ink);padding:8px 16px;text-decoration:none;cursor:pointer}button:hover,a.button:hover{background:var(--panel)}a{color:inherit;text-underline-offset:3px;overflow-wrap:anywhere}h1{font-size:clamp(36px,6vw,68px);line-height:1.04;letter-spacing:-.045em;margin:36px 0 16px;font-weight:600}h2{font-size:30px;letter-spacing:-.025em;line-height:1.16;margin:0 0 18px}h3{font-size:20px;margin:0 0 12px;line-height:1.25}p{max-width:76ch;margin:0 0 16px}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}.hero{padding:36px 0 30px}.hero .art{max-width:850px;margin:24px 0 34px}.lead{font-size:20px;max-width:65ch}.note{font-size:14px;color:var(--muted)}section{padding:42px 0;border-top:1px solid var(--line)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:24px;align-items:start}.card{background:var(--panel);padding:24px;border:1px solid var(--line);border-radius:12px;overflow:hidden}.tag{display:inline-block;padding:3px 10px;border:1px solid var(--line);border-radius:20px;font-size:12px;margin:0 0 16px}.art{display:block;max-width:100%}.art img{display:block;width:100%;height:auto;max-width:100%}.negative{display:none!important}.dark .positive{display:none!important}.dark .negative{display:block!important}.source{background:white;border:1px solid #ddd;border-radius:8px;width:100%;padding:8px}.source img{width:100%;display:block}.specimen{overflow:auto;max-width:100%;padding:18px 0;display:flex;gap:20px;align-items:center}.fixedrow{overflow:auto;max-width:100%;border-top:1px solid var(--line);padding:18px 0}.fixedrow .label{font-size:13px;color:var(--muted);margin:4px 0 0}.icon{display:inline-block;flex:none}.icon img{display:block;flex:none;max-width:none}svg{display:block;width:100%;height:auto;overflow:hidden}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;vertical-align:top;padding:12px 10px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{font-size:12px;font-weight:600;color:var(--muted)}td:first-child{font-weight:500}ul{padding-left:20px;margin:12px 0}li{margin:8px 0}.keyline{border-left:3px solid var(--ink);padding-left:18px;margin:20px 0}.downloads{display:flex;gap:8px;flex-wrap:wrap}.tight{max-width:48ch}.two-lines{display:grid;gap:20px}details{border:1px solid var(--line);border-radius:8px;padding:16px;margin-top:20px}summary{cursor:pointer;font-weight:500}dialog{background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:12px;padding:16px;max-width:calc(100vw - 16px)}dialog::backdrop{background:#0009}iframe{box-sizing:content-box;border:1px solid var(--line);max-width:100%;display:block;background:white;margin-top:12px}.compact nav,.compact #narrow{display:none}.compact main{padding:20px}.compact h1{font-size:36px}.compact section{padding:28px 0}@media(max-width:600px){main{padding:20px}h2{font-size:25px}.card{padding:18px}.lead{font-size:18px}th,td{padding:9px 6px;font-size:12px}nav .eyebrow{width:100%}}@media print{nav,dialog{display:none}body{--bg:white;--ink:#151515;--muted:#666;--line:#ddd;--panel:#f7f7f7}section,.card{break-inside:avoid}.negative{display:none!important}.positive{display:block!important}main{padding:0}}
</style><body><main><nav><span class="eyebrow">Loam / Construction master 1.0</span><div><button id="theme">Dark background</button><button id="narrow">375 px layout</button><a class="button" href="https://github.com/loamcommons/design-system/archive/refs/heads/main.zip">Download source package</a></div></nav>
'''
body=f'''<header class="hero"><p class="eyebrow">A reproducible identity, reconstructed from the original</p><h1>One L. One family.</h1>{art('loam-wordmark')}<p class="lead">Use the L as the first letter of Loam. Retain the same L inside the Commons monogram. The outlines and spacing now come from a single editable source.</p><p class="note">Design judgment informed by one Claude Desktop consultation in three rounds. Human recognition, legal distinctiveness and long-term durability remain unverified. The canonical LC avatar and Loam social preview were deployed to GitHub on October 18, 2026.</p></header>
<section id="arrangements"><p class="eyebrow">Exactly two arrangements</p><h2>The initial should do one job.</h2><div class="grid"><article class="card" id="arrangement-a"><span class="tag">A · Symbol beside “loam”</span>{art('comparison-symbol-beside')}<p>The full name remains explicit, but the two L forms create a redundant opening. The symbol uses the original Commons scale, offset and gap: its height is 2.53× the lettering’s x-height.</p><p class="note">Claude first read “L loam.” In the final comparison, restoring the original proportions made the separate L too dominant for the short product name.</p></article><article class="card" id="arrangement-b"><span class="tag">B · L followed by “oam” · Recommended</span>{art('loam-wordmark')}<p>The symbol becomes the initial. The round letters use an 880-unit x-height against the L’s 1000-unit height, bringing their strokes close in weight.</p><p class="note">Claude first read “Loam” and preferred this final arrangement after the L–o spacing repair.</p></article></div><p class="note" style="margin-top:16px">These cards fit their available width. The actual-size specimens below use fixed CSS dimensions. Different mark scales are deliberate role changes; the L path itself never changes.</p></section>
<section id="reference"><p class="eyebrow">Measured</p><h2>Keep the original. Remove the drift.</h2><div class="source"><img src="data:image/png;base64,{original}" alt="Untouched original transparent Loam Commons artwork, shown on white"></div><p style="margin-top:20px">The first transparent composition is authoritative for reconstruction because it supplies L, C and lettering together. Its original alpha channel survives. Later square and social images are generated interpretations with baked-in backgrounds; their greater pixel counts do not make them better specifications.</p><div class="tablewrap"><table><thead><tr><th>Untouched reference</th><th>L width ÷ height</th><th>Stem ÷ height</th><th>Role</th></tr></thead><tbody><tr><td>Original transparent composition</td><td>0.9274</td><td>0.2310</td><td>Reconstruction reference</td></tr><tr><td>Square LC</td><td>0.9545</td><td>0.2438</td><td>Drift evidence</td></tr><tr><td>Square L</td><td>0.9439</td><td>0.2443</td><td>Drift evidence</td></tr><tr><td>L-only social image</td><td>0.9923</td><td>0.2586</td><td>Drift evidence</td></tr><tr><td>L + loam social image</td><td>0.9480</td><td>0.3303</td><td>Drift evidence</td></tr></tbody></table></div><p class="note" style="margin-top:14px">Operational measurements: alpha ≥128 and RGB mean &lt;128; the L stem is measured halfway down its bounding box. Threshold sensitivity is recorded separately. These ratios describe pixels, not an exact original design. <a href="evidence/reproducible-measurements.json">Measurements and hashes</a> · <a href="reference/loamcommons-logo.png">Untouched original</a></p></section>
<section id="geometry"><p class="eyebrow">Deliberately constructed</p><h2>Small path vocabulary. Explicit coordinates.</h2><div class="grid"><div>{construction}<p class="note">Construction guide. Dashed box denotes 200-unit clear space. Authoritative coordinates are in <a href="source/master.json">master.json</a>.</p></div><div><table><tbody><tr><td>Reference unit H</td><td>L height = 1000</td></tr><tr><td>L bounds</td><td>0,0 to 928,1000</td></tr><tr><td>L stem / base</td><td>231 / 221</td></tr><tr><td>L contour</td><td>4 cubic segments, straight joins, 1 closed contour</td></tr><tr><td>C bounds</td><td>284,0 to 930,835</td></tr><tr><td>C contour</td><td>7 cubic segments, straight joins, 1 closed contour</td></tr><tr><td>LC channels</td><td>53 upright gap; approximately 48 minimum outline clearance</td></tr><tr><td>Clear space</td><td>At least 0.2H on every side; included in each SVG</td></tr><tr><td>Color</td><td>#151515 positive; #FFFFFF reverse; transparent canvas</td></tr></tbody></table><p class="note" style="margin-top:16px">Curves regularize the original’s asymmetries; they are a new exact specification. The top and foot terminals remain distinct. No live strokes, fonts, clipping masks, filters or external image dependencies appear in canonical SVGs.</p></div></div></section>
<section id="lettering"><p class="eyebrow">Reproducible lettering</p><h2>Outlines, not a guessed font.</h2>{art('loamcommons-wordmark')}<div class="grid"><div><h3>One set of seven glyphs</h3><p>l, o, a, m, c, n and s are custom outlined reconstructions. Every repeated o and m references the same path. This is a logo alphabet only, not a general text typeface.</p><p>The s is the largest local departure from the original. Its upper terminal and lower curve are deliberately redrawn for a smooth, coherent alphabet; it is not an exact trace.</p><p>The glyph grid uses x-height 1000, flat baseline 1000 and l ascender −567. Round forms extend to −25 and 1025. The o uses cubic approximations to a slightly wide ellipse, with a circular counter.</p></div><div><h3>Optical decisions</h3><p>The 25-unit round overshoot keeps circles from looking short beside flat stems. The original’s wider vertical stem and thinner L foot remain. The m has two equal 379.5-unit counters and translated matching inner arches, with three 233-unit stems. Flat color removes generated texture.</p><p>In Loam, the o starts at x=880, with x-height 880 and baseline 1000. Its bounding box overlaps the L’s horizontally, but the contours stay separate. Minimum numerical clearance is approximately 92.2 units—2.9 CSS pixels at the supported wordmark minimum.</p></div></div><details><summary>Exact layout values</summary><div class="tablewrap"><table><thead><tr><th>Asset</th><th>Mark scale</th><th>Text scale / origin</th><th>Ink bounds W × H</th></tr></thead><tbody><tr><td>L</td><td>1</td><td>—</td><td>928 × 1000</td></tr><tr><td>LC</td><td>1</td><td>—</td><td>930 × 1000</td></tr><tr><td>Loam / B</td><td>1</td><td>0.88 / (880,120)</td><td>4194.08 × 1022</td></tr><tr><td>Loam Commons</td><td>1</td><td>0.396 / (1211,442)</td><td>6164.168 × 1000</td></tr><tr><td>Comparison / A</td><td>1</td><td>0.396 / (1211,442)</td><td>2840.936 × 1000</td></tr></tbody></table></div><p class="note">Within “oam”, glyph origins are o=0, a=1125, m=2308 before the 0.88 scale. All remaining glyph positions are explicit in the source. Uniform scaling only; do not reset tracking, substitute a font or stretch the marks.</p></details></section>
<section id="screen"><p class="eyebrow">Observed screen support</p><h2>Actual size, on both backgrounds.</h2><p>Use the background button to inspect the exact same outlines in reverse. These are screen minima for the inspected renderings; print, embroidery, engraving and unfamiliar displays need their own production proof.</p><div class="specimen">{icon('loam-mark',24)}{icon('loam-mark',48)}{icon('loamcommons-mark',48)}{icon('loamcommons-mark',96)}</div><p class="note">L square canvas: 24 / 48 CSS px. LC square canvas: 48 / 96 CSS px. Included clear space reduces ink height to 71.4% of the square.</p><div class="fixedrow">{art('loam-wordmark',height=32)}<p class="label">Loam · 32 px ink height · about 144 px canvas width</p></div><div class="fixedrow">{art('loamcommons-wordmark',height=48)}<p class="label">Loam Commons · 48 px ink height · about 316 px canvas width</p></div><div class="fixedrow">{art('comparison-symbol-beside',height=40)}<p class="label">A comparison · 40 px ink height</p></div><p class="note">Small specimens remain fixed-size. On very narrow screens this row may scroll rather than secretly shrink. The PNG set includes matching 1×/2× icon exports and small wordmark exports.</p></section>
<section id="evidence"><p class="eyebrow">Evidence and limits</p><h2>What is established—and what remains a judgment.</h2><div class="grid"><article><h3>Mechanically checked</h3><ul><li>Original source file hashes are unchanged.</li><li>Each SVG embeds exactly the same L path from the one master definition.</li><li>All contours close; cubic extrema fit declared ink bounds and clear-space canvases.</li><li>SVG references are local; no font or network dependency can change lettering.</li><li>PNG dimensions, alpha channel and clear borders pass the finite export audit.</li></ul><p class="note"><a href="evidence/verification.json">Verification receipt</a> · <a href="evidence/clearance.json">Numerical clearance bounds</a></p></article><article><h3>Reviewed, not proved</h3><p>Claude Desktop first read B as “Loam,” then identified a tight L–o join and unequal m counters. After those repairs and a fair comparison at matching x-height, its final review favored B. It withdrew an apparent weight concern after checking the measured source overlay. The review summary records the repairs, changed recommendation and remaining disagreements.</p><p>Keep LC for Commons: the owner’s first reading was an L supporting and sheltering a nested C, almost maternally. That makes the intended relationship care for the commons: Loam provides the substrate that lets it flourish. The outward-open form gives this reading room; it does not establish how other viewers will interpret it. Keep L as the product companion, while leaving its standalone distinctiveness unresolved. A future small product icon merits focused design work; the evidence does not justify replacing the whole family.</p><p>One model consultation is not a human reader study. Recognition rates, distinctiveness among competing identities, legal clearance and decades of suitability are not established.</p><p class="note"><a href="evidence/review.md">Review and decisions</a></p></article></div></section>
<section id="files"><p class="eyebrow">Editable delivery</p><h2>Build every asset from the master.</h2><p>Edit <a href="source/master.json">master.json</a>, then run the included builder with Python. SVG creation uses only the Python standard library; PNG rendering additionally uses librsvg. The verifier checks artifact contracts, and the measurement script re-reads the untouched source PNGs.</p><div class="downloads"><a class="button" href="svg/loam-wordmark.svg">Loam SVG</a><a class="button" href="svg/loamcommons-wordmark.svg">Commons SVG</a><a class="button" href="svg/loam-mark-square.svg">L icon SVG</a><a class="button" href="svg/loamcommons-mark-square.svg">LC icon SVG</a><a class="button" href="README.md">Build instructions</a></div><p class="note" style="margin-top:20px">Design source: the existing artwork’s monochrome palette and geometric lettering. This guide introduces no new brand palette or visual theme. SVG path and coordinate behavior follows <a href="https://www.w3.org/TR/SVG2/paths.html">SVG 2 paths</a> and <a href="https://www.w3.org/TR/SVG2/coords.html">coordinate systems</a>. <a href="https://www.ibm.com/design/language/ibm-logos/8-bar/">IBM’s master/optical-variant guidance</a> is a professional precedent for controlled artwork, not a source of Loam proportions.</p></section>
</main><dialog id="mobile"><button id="close">Close narrow view</button><iframe id="frame" title="375 CSS pixel viewport" width="375" height="700"></iframe></dialog><script>const t=document.getElementById('theme');t.onclick=()=>{{document.body.classList.toggle('dark');t.textContent=document.body.classList.contains('dark')?'Light background':'Dark background'}};document.getElementById('narrow').onclick=()=>{{document.getElementById('frame').src='index.html?compact=1';document.getElementById('mobile').showModal()}};document.getElementById('close').onclick=()=>document.getElementById('mobile').close();if(location.search.includes('compact=1'))document.body.classList.add('compact');</script></body></html>'''
(R/'index.html').write_text(head+body)
